/**
 * SPA i18n runtime - a tiny t() catalog lookup, no framework.
 *
 * English is the key: t('Save Profile') renders literally in English builds,
 * and as an identity fallback for any string not yet translated (or not yet
 * wrapped in t() at all) - the app never breaks, it just shows English. Locale
 * catalogs are flat { "English string": "translated string" } JSON files under
 * ./locales, generated by scripts/translate.ts, loaded as one dynamic-import
 * chunk per language so English users (the default) pay zero extra bytes.
 *
 * Preference storage mirrors theme.ts exactly: canonical on `profile.lang`,
 * mirrored to `localStorage 'lang'` for the pre-paint <html lang> read (see the
 * inline script in index.html), reconciled from the profile in main.ts's boot().
 */

// Deep engine imports, NOT the `@lolly/engine` barrel: this module is on the
// boot path, and engine/src/index.ts is one shared facade whose retained export
// set is the UNION over every importer - touching it here drags createRuntime
// (Handlebars) + loadTool/validate (Ajv) + c2pa onto first paint. See
// scripts/check-bundle-budget.ts.
import { LANGS, LANG_META, normalizeLang, flagEmoji, sortedLangs } from '../../../engine/src/lang.ts';
import type { Lang, LangSort } from '../../../engine/src/lang.ts';
// utils.ts is a dependency-free leaf (escape/safeHref/NAV_EVENTS only), so this
// adds nothing to the boot chunk and cannot cycle back into i18n.
import { escape } from './utils.ts';

export { LANGS, LANG_META, normalizeLang, flagEmoji, sortedLangs };
export type { Lang, LangSort };

