type NonEnglishLang = Exclude<Lang, 'en'>;

const LOADERS: Record<NonEnglishLang, () => Promise<{ default: Record<string, string> }>> = {
  es: () => import('./locales/es.json'),
  de: () => import('./locales/de.json'),
  fr: () => import('./locales/fr.json'),
  zh: () => import('./locales/zh.json'),
  ja: () => import('./locales/ja.json'),
  vi: () => import('./locales/vi.json'),
  pt: () => import('./locales/pt.json'),
  'zh-hant': () => import('./locales/zh-hant.json'),
  cs: () => import('./locales/cs.json'),
  nl: () => import('./locales/nl.json'),
  tl: () => import('./locales/tl.json'),
  sv: () => import('./locales/sv.json'),
  ms: () => import('./locales/ms.json'),
  ro: () => import('./locales/ro.json'),
  hi: () => import('./locales/hi.json'),
  bn: () => import('./locales/bn.json'),
  ur: () => import('./locales/ur.json'),
  id: () => import('./locales/id.json'),
  ar: () => import('./locales/ar.json'),
  bg: () => import('./locales/bg.json'),
  tr: () => import('./locales/tr.json'),
  uk: () => import('./locales/uk.json'),
  pl: () => import('./locales/pl.json'),
  it: () => import('./locales/it.json'),
  no: () => import('./locales/no.json'),
  ko: () => import('./locales/ko.json'),
};

/**
 * A body of copy big enough to keep OUT of the boot catalog, loaded only by the
 * view that renders it.
 *
 *  - `caps` - the ~300 prose strings of the capability map
 *    (lib/capabilities-data.ts), which only the #/d?tab=caps panel ever shows. At
 *    ~22 KB of English source it would be a fifth of every non-English user's
 *    boot-time catalog download, for a panel most of them never open.
 *  - `collab` - the private-collab surface (the invite/join ceremony, the #/join
 *    route, the beam consent toast and its pack labels, the collaborator pill and
 *    the focus rings). ~180 strings that appear only once a collab is actually
 *    being started or joined, and every surface that renders them has an async
 *    entry (route handler, dialog open, mount) to await this from - so they load
 *    with the ceremony instead of with the app. (The `private-collab` flag went ON
 *    by default on 2026-08-10; the namespace is lazy because of WHEN this copy is
 *    needed, not because a flag hid it.) The eight strings that render on ORDINARY
 *    chrome - the profile Feature-flags row and the two Share-dialog rows - are
 *    deliberately NOT here; they are plain `t()` call sites in the boot catalog.
 *
 * A namespace catalog is a plain flat { english: translated } file exactly like a
 * locale catalog - same t(), same English-key-is-the-fallback contract - written
 * by scripts/translate.ts's corpus of the same name into ./locales/<ns>/<lang>.json.
 */
export type Namespace = 'caps' | 'collab';

// One loader per namespace, mirroring LOADERS above: a static path prefix with a
// single `${lang}` segment, so Vite emits one analyzable chunk per (namespace,
// language) and a locale only ever fetches its own. English never calls these.
//
// Every namespace must have a catalog file per language on disk even before it is
// translated (the pipeline writes English-valued ones): Rollup's dynamic-import-vars
// transform resolves this template against the files that exist at BUILD time and
// fails the build outright for a directory with none.
const NAMESPACE_LOADERS: Record<Namespace, (lang: NonEnglishLang) => Promise<{ default: Record<string, string> }>> = {
  caps: (lang) => import(`./locales/caps/${lang}.json`),
  collab: (lang) => import(`./locales/collab/${lang}.json`),
};

let active: Lang = 'en';
/** The language the CURRENT `catalog` belongs to, which is not always `active`:
 *  setActiveLang assigns `active` synchronously and only then awaits the locale
 *  chunk, so in between, t() is still answering in English under a non-English
 *  `active`. English starts out true of both - the English "catalog" is the empty
 *  map, in effect from the first tick. See loadedLang(). */
let loadedCatalogLang: Lang = 'en';
let catalog: Record<string, string> = {};
/** Namespaces merged into `catalog`, keyed `<lang>:<ns>` - a language switch
 *  rebuilds the catalog, so the same namespace must load again for the new one. */
const loadedNamespaces = new Set<string>();
const listeners = new Set<(lang: Lang) => void>();

/**
 * Merge a namespace's strings into the active catalog. Idempotent, and a no-op in
 * English (where every key already IS its own value). Call it - and await it - 
 * before rendering the copy it carries; t() is unchanged either way, so a
 * namespace that hasn't been translated into this language yet (or fails to load)
 * simply leaves those strings in English, exactly like a missing key.
 *
 * Each namespace loads via its own analyzable per-language import (NAMESPACE_LOADERS),
 * so a locale only ever fetches its own chunk.
 */
export async function loadNamespace(ns: Namespace): Promise<void> {
  const key = `${active}:${ns}`;
  if (active === 'en' || loadedNamespaces.has(key)) return;
  loadedNamespaces.add(key);
  try {
    const mod = await NAMESPACE_LOADERS[ns](active);
    // Chrome strings win a key collision - a namespace can never shadow the app's
    // own UI copy, only add to it.
    catalog = { ...mod.default, ...catalog };
  } catch {
    /* not translated into this language yet → English, same as any missing key */
  }
}

/** The active language code. */
export function currentLang(): Lang {
  return active;
}

/**
 * The language whose catalog t() is actually answering from RIGHT NOW - which is
 * what a caller comparing "what did I paint?" against "what is in effect?" has to
 * read. currentLang() cannot serve there: it reports the REQUESTED language, which
 * setActiveLang assigns before it awaits the locale chunk, so a caller that samples
 * it either side of the load compares a value with itself and concludes nothing
 * changed (main.ts's post-locale re-render, plans/155 Task 3.7).
 *
 * A chunk that FAILS to load still moves this: the catalog in effect is that
 * language's, and its being empty is exactly the "missing key ⇒ English" contract,
 * not a reason to keep claiming English is still loading.
 */
export function loadedLang(): Lang {
  return loadedCatalogLang;
}

/** Native-name options for a picker, English first. */
export function langOptions(): Array<{ code: Lang; nativeName: string; flags: readonly string[] }> {
  return LANGS.map(code => ({ code, nativeName: LANG_META[code].nativeName, flags: LANG_META[code].flags ?? [] }));
}

/**
 * Resolve + load the boot-time language: an explicit override (the `lang` URL
 * param, applies for this session only) beats the saved profile, which beats
 * the localStorage mirror, which beats the browser's own language, which beats
 * English. Called once from main.ts's boot(), before the first view renders.
 */
export async function initI18n(opts: { urlLang?: string | null; profileLang?: string | null } = {}): Promise<Lang> {
  const fromUrl      = normalizeLang(opts.urlLang);
  const fromProfile  = normalizeLang(opts.profileLang);
  const fromStorage  = normalizeLang(localStorage.getItem('lang'));
  const fromBrowser  = normalizeLang(navigator.language?.split('-')[0]);
  const lang = fromUrl ?? fromProfile ?? fromStorage ?? fromBrowser ?? 'en';
  await setActiveLang(lang, { persist: false });
  return lang;
}

/**
 * Remove a `lang` URL override from the address bar - both places it can ride
 * (the search string and the hash query; mirrors main.ts's peekUrlLang). An
 * explicit picker choice supersedes the session override, which otherwise
 * out-ranks the just-persisted preference on the next boot (initI18n's
 * precedence chain) and makes the switch appear not to stick on any ?lang=
 * link. String surgery rather than URLSearchParams re-serialization, so every
 * other param's encoding (URL-mode compact forms) rides through byte-identical.
 */
function stripUrlLangOverride(): void {
  const strip = (q: string) => q.split('&').filter(p => p && p !== 'lang' && !p.startsWith('lang=')).join('&');
  const { pathname, search, hash } = window.location;
  const cleanSearch = strip(search.replace(/^\?/, ''));
  const qi = hash.indexOf('?');
  const hashPath = qi === -1 ? hash : hash.slice(0, qi);
  const hashQuery = qi === -1 ? '' : strip(hash.slice(qi + 1));
  const next = pathname + (cleanSearch ? `?${cleanSearch}` : '') + hashPath + (hashQuery ? `?${hashQuery}` : '');
  if (next !== pathname + search + hash) history.replaceState(history.state, '', next);
}

/**
 * Switch the active language: loads its catalog, updates <html lang>, and (from
 * a picker) mirrors to localStorage. Callers that also want to persist to the
 * profile do so themselves via host.profile.set - this module only owns the
 * in-memory catalog + localStorage mirror, matching theme.ts's applyTheme.
 */
export async function setActiveLang(lang: Lang, opts: { persist?: boolean } = {}): Promise<void> {
  active = lang;
  catalog = lang === 'en' ? {} : (await LOADERS[lang]().catch(() => ({ default: {} }))).default;
  loadedCatalogLang = lang;   // t() answers in `lang` from here on - see loadedLang()
  loadedNamespaces.clear(); // the catalog they were merged into is gone

  document.documentElement.lang = LANG_META[lang].htmlLang;
  // Stamp direction alongside lang (Arabic is rtl) - always set explicitly, so
  // switching AWAY from an RTL language restores ltr rather than inheriting a
  // stale dir from the previous choice.
  document.documentElement.dir = LANG_META[lang].dir ?? 'ltr';
  if (opts.persist) {
    localStorage.setItem('lang', lang);
    // persist ⇒ an explicit user choice - clear any session `lang` override
    // from the URL so it can't out-rank this choice on the next (re)load.
    stripUrlLangOverride();
  }
  listeners.forEach(fn => { try { fn(lang); } catch (e) { console.error(e); } });
}

/** The slice of the host bridge a language picker needs to persist its choice. */
export interface LangSwitchHost {
  profile: { get(): Promise<object>; set?(profile: object): Promise<unknown> };
}

/**
 * Switch the active language from a picker: persists to profile.lang (dropped
 * entirely for 'en', matching the profile view's original behaviour), then
 * reloads so the whole app - not just the caller's own wave-1-wrapped strings - 
 * re-renders in the new language. Shared by the profile card's picker and the
 * gallery/catalog/projects lang-fab menu.
 */
export async function switchLang(host: LangSwitchHost, next: Lang): Promise<void> {
  if (next === currentLang()) return;
  try {
    const current = await host.profile.get();
    const { lang: _drop, ...rest } = current as Record<string, unknown>;
    await host.profile.set?.(next === 'en' ? rest : { ...rest, lang: next });
  } catch { /* preference save is best-effort - the switch below still applies for this session */ }
  await setActiveLang(next, { persist: true });
  window.location.reload();
}

/**
 * URL for a docs (/info) page in the currently active app language. English is
 * unprefixed (`/info/<slug>.html`); every other locale lives under
 * `/info/<lang>/<slug>.html` - mirrors docs/build.ts's localeHref exactly
 * (duplicated, not imported: that's a static-site generator with no shared
 * module boundary with this SPA - see its own copy right next to
 * LANG_ICON_SVG). `slug` is 'index' for the docs homepage - ALWAYS keep the
 * explicit `index.html` filename here (never shorten to a bare `/info/` or
 * `/info/<lang>/` directory URL): the dev server's static-file middleware
 * (shells/web/vite.config.js's serveRepoStatic) only resolves a bare
 * directory to index.html for the literal `/info`/`/info/` root, not for a
 * `/info/<lang>/` subpath - an omitted filename there 404s through to the
 * SPA fallback instead of the docs page.
 */
export function docsHref(slug: string): string {
  return docsInfoHref(slug);
}

/**
 * The built /info page path for `slug` in an explicit `lang` (defaults to the
 * active app language) - English unprefixed, every other locale under
 * `/info/<lang>/…`. This is BOTH the crawlable/share URL (what docsHref returns)
 * AND the fetch source the in-app reader (#/docs, views/docs.ts) rehosts, which
 * is why it takes an explicit lang: the reader may render a page in a language
 * pinned by the route rather than the current UI locale. Same explicit-filename
 * rule as docsHref (see its note): `index` → `index.html`, never a bare dir URL.
 */
export function docsInfoHref(slug: string, lang: Lang = currentLang()): string {
  const file = slug === 'index' ? 'index.html' : `${slug}.html`;
  return lang === 'en' ? `/info/${file}` : `/info/${lang}/${file}`;
}

/**
 * The IN-APP docs reader route (`#/docs/<slug>`) - the live, active-brand
 * counterpart to docsHref's static /info page, for INTERNAL navigation (the
 * language rides the app's current locale, so the hash stays clean/unprefixed).
 * Share and SEO links stay on docsHref (`/info/…`): the hash route is not
 * separately crawlable, and a shared link should land anyone on the static page.
 */
export function docsAppHref(slug: string): string {
  return `#/docs/${slug}`;
}

/** Shared interpolation. `esc` decides whether a param is HTML-escaped. */
function interpolate(source: string, params: Record<string, string | number> | undefined, esc: boolean): string {
  let out = catalog[source] ?? source;
  if (params) {
    for (const [key, value] of Object.entries(params)) {
      const v = String(value);
      out = out.replaceAll(`{${key}}`, esc ? escape(v) : v);
    }
  }
  return out;
}

/**
 * Translate a UI string. The English source doubles as the lookup key, so an
 * untranslated (or not-yet-wrapped) string simply renders as English instead of
 * breaking. `params` does plain {name} interpolation.
 *
 * **Interpolated params are HTML-escaped.** t()'s result is routinely assigned
 * to `innerHTML`, so safety must not rest on every caller remembering to escape
 * (SUSE assessment 2026-08, S5). The catalog string ITSELF is still raw, because
 * translations intentionally carry markup (`'Up to <strong>{n}</strong>…'`) - 
 * that is the locale-file trust boundary documented in docs/threat-model.md.
 *
 * Use {@link tRaw} instead when the result does NOT go to an HTML sink - text
 * assigned to `textContent`, `document.title`, `announce()`, `setAttribute`, or
 * a string that is itself about to be `escape()`d - or when a param is meant to
 * be markup. Escaping there would render `O&#39;Brien` to the user.
 */
export function t(source: string, params?: Record<string, string | number>): string {
  return interpolate(source, params, true);
}

/**
 * t() without param escaping - the pre-2026-08 behaviour, kept for the two
 * legitimate cases: a TEXT sink (where entities would be shown literally) and a
 * param that is intentionally HTML. Every tRaw() call in an HTML context is a
 * site a reviewer must check by hand, so prefer t() unless you know why.
 */
export function tRaw(source: string, params?: Record<string, string | number>): string {
  return interpolate(source, params, false);
}
